import sys

def is_magical(n):
    s = str(n)
    has_odd_digit = False
    has_non_zero_even_digit = False

    for char in s:
        digit = int(char)
        if digit % 2 == 1:
            has_odd_digit = True
        elif digit % 2 == 0 and digit != 0:
            has_non_zero_even_digit = True

        if has_odd_digit and has_non_zero_even_digit:
            return True

    return not has_odd_digit

def find_kth_magical(k):
    count = 0
    num = 0

    while count < k:
        if is_magical(num):
            count += 1
        if count == k:
            return num
        num += 1

def main():
    import sys
    input = sys.stdin.read().split()
    t = int(input[0])
    results = []
    index = 1
    for _ in range(t):
        k = int(input[index])
        results.append(find_kth_magical(k))
        index += 1
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
